///
/// Return `Some` to set `size`; the first part returning `Some` wins.
fn tooltip_component(&self, host: &dyn ClientHost, event: &mut TooltipComponentEvent<'_>) -> Option < [f32 ; 2] > { let _ = host;let _ = event; None }
