fn damage_item(&self, host: &mut dyn ServerHost, event: &mut DamageItemEvent<'_>) -> Flow { let _ = host;let _ = event; Flow::Continue }
/// `IDispensibleContainerItemExtension.emptyContents`: `stack` (a bucket
